arguments.new_string:
const visible = visiblePrefix(streamBufRef.current);
// Cap by *rendered* rows: wrapped lines count as multiple rows, or the
// region overflows the fixed-height frame and corrupts the redraw.
const cols = Math.max(40, (process.stdout.columns ?? 100) - 6);
const budget = Math.max(4, rowsRef.current - 16);
const lines = visible.split("\n");
const kept: string[] = [];
let rows = 0;
for (let i = lines.length - 1; i >= 0 && rows < budget; i--) {
  rows += Math.max(1, Math.ceil(lines[i].length / cols));
  kept.unshift(lines[i]);
}
setStream(kept.join("\n"));
